# RICD — lote L25, parte d: arts. 1 a 21 (sede, sessões, posse, Mesa, Líderes, Presidência, órgãos)
Q = []
_n=[0]
FG={"tipo":"regimento","ref":"Regimento Interno da Câmara dos Deputados, 29ª ed., Edições Câmara, 2025","versao":"atualizado até a Resolução nº 16/2025 (15/5/2025)","conferida":"texto-fonte"}
def R(ponto, arts, padE, dif, C, E, com, terro):
    _n[0]+=1; tag=f"d{_n[0]:03d}"
    ex={"fonte":dict(FG,ref=FG["ref"]+", "+", ".join("art. "+a for a in arts))}
    Q.append((ponto, arts, "C", padE, dif, C, com, "", tag, ex))
    Q.append((ponto, arts, "E", padE, dif, E, com, terro, tag, ex))
# R27 sede, sessões legislativas, posse
R("R27",["1"],"troca_efeito",3,"Havendo motivo relevante ou de força maior, a Câmara pode, por deliberação da Mesa, ad referendum da maioria absoluta dos Deputados, reunir-se fora do Palácio do Congresso.","Havendo motivo relevante ou de força maior, o Presidente pode, sozinho, transferir a reunião da Câmara para outro edifício, sem necessidade de referendo.","Art. 1º, p. único.","dispensa deliberação e referendo")
R("R27",["2"],"troca_efeito",3,"As sessões legislativas ordinárias vão de 2 de fevereiro a 17 de julho e de 1º de agosto a 22 de dezembro.","As sessões legislativas ordinárias vão de 1º de fevereiro a 30 de junho e de 1º de agosto a 15 de dezembro.","Art. 2º, I.","troca as datas")
R("R27",["2"],"troca_efeito",3,"As reuniões marcadas para 2 de fevereiro, 17 de julho, 1º de agosto ou 22 de dezembro que caírem em fim de semana ou feriado são transferidas para o primeiro dia útil subsequente.","As reuniões marcadas para essas datas que caírem em fim de semana ou feriado são antecipadas para o último dia útil anterior.","Art. 2º, § 1º.","antecipa em vez de adiar")
R("R27",["2"],"troca_efeito",3,"A primeira e a terceira sessões legislativas ordinárias de cada legislatura são precedidas de sessões preparatórias.","Todas as sessões legislativas ordinárias são precedidas de sessões preparatórias.","Art. 2º, § 2º.","generaliza")
R("R27",["2"],"troca_efeito",3,"A sessão legislativa ordinária não é interrompida em 17 de julho enquanto o Congresso não aprovar a lei de diretrizes orçamentárias.","A sessão legislativa ordinária não é interrompida em 17 de julho enquanto o Congresso não aprovar a lei orçamentária anual.","Art. 2º, § 3º.","troca LDO por LOA")
R("R27",["2"],"restricao_indevida",3,"Em convocação extraordinária do Congresso Nacional, a Câmara delibera somente sobre a matéria objeto da convocação.","Em convocação extraordinária do Congresso Nacional, a Câmara pode deliberar também sobre matéria urgente alheia à convocação.","Art. 2º, § 4º.","amplia o objeto")
R("R27",["3"],"troca_efeito",3,"O diplomado deve apresentar à Mesa o diploma e a comunicação de nome parlamentar, legenda e unidade da Federação até 31 de janeiro do ano de instalação da legislatura.","O diplomado deve apresentar à Mesa o diploma, pessoalmente e sem intermediação do Partido, até 1º de março do ano de instalação da legislatura.","Art. 3º.","troca prazo e veda o Partido")
R("R27",["3"],"troca_efeito",3,"O nome parlamentar compõe-se, em regra, de dois elementos: um prenome e o nome, dois nomes ou dois prenomes.","O nome parlamentar compõe-se, em regra, de três elementos: prenome, nome e sobrenome.","Art. 3º, § 1º.","troca número de elementos")
R("R27",["3"],"troca_efeito",3,"A relação dos Deputados diplomados é feita por unidade da Federação, de norte a sul, na ordem geográfica das capitais, e, em cada uma, em ordem alfabética dos nomes parlamentares.","A relação dos Deputados diplomados é feita em ordem alfabética nacional, sem agrupamento por unidade da Federação.","Art. 3º, § 3º.","muda o critério")
R("R27",["4"],"troca_efeito",3,"A sessão preparatória de instalação da legislatura realiza-se em 1º de fevereiro do primeiro ano, na sede da Câmara.","A sessão preparatória de instalação da legislatura realiza-se em 2 de fevereiro do primeiro ano, no Plenário do Senado.","Art. 4º.","troca data e local")
R("R27",["4"],"troca_efeito",3,"Assume a direção da sessão preparatória o último Presidente, se reeleito Deputado; na sua falta, o Deputado mais idoso dentre os de maior número de legislaturas.","Assume a direção da sessão preparatória o último Presidente, ainda que não reeleito; na sua falta, o Deputado mais idoso, independentemente do número de legislaturas.","Art. 4º, § 1º.","dispensa reeleição e legislaturas")
R("R27",["4"],"troca_efeito",3,"Aberta a sessão preparatória, o Presidente convida quatro Deputados, de preferência de Partidos diferentes, para servirem de Secretários.","Aberta a sessão preparatória, o Presidente convida dois Deputados do mesmo Partido para servirem de Secretários.","Art. 4º, § 2º.","troca número e Partidos")
R("R27",["4"],"troca_efeito",4,"O compromisso de posse não pode ter o conteúdo ou o ritual modificados, nem admite declaração oral ou escrita no ato, nem posse por procurador.","O compromissando pode apresentar declaração escrita no ato da posse ou ser empossado por procurador, em caso de enfermidade.","Art. 4º, § 4º.","admite procurador")
R("R27",["4"],"troca_efeito",3,"O Deputado empossado posteriormente presta o compromisso em sessão e junto à Mesa, exceto no recesso, quando o faz perante o Presidente.","O Deputado empossado posteriormente presta o compromisso sempre perante o Presidente, em seu gabinete.","Art. 4º, § 5º.","generaliza o gabinete")
R("R27",["4"],"troca_efeito",4,"Salvo força maior ou enfermidade comprovadas, a posse dá-se em trinta dias, prorrogáveis por igual período a requerimento do interessado.","Salvo força maior ou enfermidade comprovadas, a posse dá-se em quinze dias, prorrogáveis por mais quinze, de ofício.","Art. 4º, § 6º.","troca prazo e iniciativa")
R("R27",["4"],"troca_efeito",4,"O Suplente que prestou o compromisso uma vez fica dispensado de fazê-lo em convocações subsequentes.","O Suplente deve renovar o compromisso a cada nova convocação.","Art. 4º, § 7º.","exige renovação")
R("R27",["4"],"troca_efeito",3,"Não se considera investido no mandato de Deputado quem deixar de prestar o compromisso nos estritos termos regimentais.","Considera-se investido no mandato o diplomado cujo diploma tenha sido apresentado, ainda que não preste o compromisso regimental.","Art. 4º, § 8º.","dispensa o compromisso")
R("R27",["4"],"troca_efeito",4,"Em licença-gestante, a declaração de parto em período inferior a 120 dias assegura o direito à posse virtual da parlamentar diplomada.","Em licença-gestante, a posse virtual da parlamentar diplomada depende de decisão discricionária do Presidente.","Art. 4º, § 6º-B.","torna discricionário")
# R28 eleição da Mesa
R("R28",["5"],"troca_efeito",3,"A Mesa é eleita para mandato de dois anos, vedada a recondução para o mesmo cargo na eleição imediatamente subsequente.","A Mesa é eleita para mandato de quatro anos, permitida uma recondução para o mesmo cargo.","Art. 5º.","troca mandato e recondução")
R("R28",["5"],"excecao_omitida",3,"Não se considera recondução a eleição para o mesmo cargo da Mesa em legislaturas diferentes, ainda que sucessivas.","Considera-se recondução, vedada, a eleição para o mesmo cargo da Mesa em legislaturas sucessivas.","Art. 5º, § 1º.","omite a exceção")
R("R28",["5"],"troca_efeito",3,"Enquanto não for escolhido o Presidente, não se procede à apuração para os demais cargos da Mesa.","A apuração dos cargos da Mesa é simultânea, podendo o Presidente ser definido por último.","Art. 5º, § 2º.","inverte a ordem")
R("R28",["6"],"troca_efeito",3,"No terceiro ano da legislatura, a eleição da Mesa ocorre antes de inaugurada a sessão legislativa, sob a direção da Mesa anterior.","No terceiro ano da legislatura, a eleição da Mesa ocorre em 1º de fevereiro, sob a direção do Deputado mais idoso.","Art. 6º.","troca a direção")
R("R28",["6"],"troca_efeito",3,"Enquanto não for eleito o novo Presidente, dirige os trabalhos a Mesa da sessão legislativa anterior.","Enquanto não for eleito o novo Presidente, dirige os trabalhos o Deputado mais idoso dentre os de maior número de legislaturas.","Art. 6º, § 3º.","troca o dirigente")
R("R28",["7"],"troca_efeito",4,"A eleição da Mesa é por escrutínio secreto e sistema eletrônico, exigida maioria absoluta no primeiro escrutínio e maioria simples no segundo, presente a maioria absoluta dos Deputados.","A eleição da Mesa é por votação ostensiva e nominal, exigida maioria simples em qualquer escrutínio, presente um terço dos Deputados.","Art. 7º, caput.","troca votação e quóruns")
R("R28",["7"],"troca_efeito",3,"Se no primeiro escrutínio ninguém alcançar a maioria absoluta, faz-se segundo escrutínio com os dois mais votados para o cargo.","Se no primeiro escrutínio ninguém alcançar a maioria absoluta, faz-se segundo escrutínio com os três mais votados para o cargo.","Art. 7º, III.","troca número")
R("R28",["7"],"troca_efeito",3,"Em caso de empate na eleição da Mesa, considera-se eleito o candidato mais idoso dentre os de maior número de legislaturas.","Em caso de empate na eleição da Mesa, o Presidente desempata pelo voto de qualidade.","Art. 7º, IV.","troca critério")
R("R28",["7"],"troca_efeito",4,"Em caso de avaria do sistema eletrônico, a eleição da Mesa faz-se por cédulas, com quatro urnas: duas para o Presidente e duas para os demais membros.","Em caso de avaria do sistema eletrônico, a eleição da Mesa faz-se por aclamação.","Art. 7º, p. único.","troca por aclamação")
R("R28",["8"],"troca_efeito",3,"Na composição da Mesa assegura-se, tanto quanto possível, a representação proporcional dos Partidos ou Blocos Parlamentares, sem prejuízo de candidaturas avulsas oriundas das mesmas bancadas.","Na composição da Mesa assegura-se, obrigatoriamente, a divisão igualitária de cargos entre os Partidos, vedadas candidaturas avulsas.","Art. 8º.","veda candidaturas avulsas")
R("R28",["8"],"troca_efeito",4,"Vagando cargo na Mesa até 30 de novembro do segundo ano de mandato, é preenchido por eleição em cinco sessões; depois dessa data, a Mesa designa um titular para responder pelo cargo.","Vagando cargo na Mesa em qualquer época, é preenchido por eleição em cinco sessões.","Art. 8º, § 2º.","omite o marco de 30 de novembro")
R("R28",["8"],"excecao_omitida",3,"É assegurada a participação de um membro da Minoria na Mesa, ainda que pela proporcionalidade não lhe caiba lugar.","A participação da Minoria na Mesa depende da proporcionalidade, não sendo assegurada quando não lhe caiba lugar.","Art. 8º, § 3º.","omite a garantia")
R("R28",["8"],"troca_efeito",4,"As vagas de cada Partido ou Bloco na Mesa são definidas pelo número de eleitos conforme o resultado da Justiça Eleitoral, desconsideradas mudanças posteriores de filiação.","As vagas de cada Partido ou Bloco na Mesa são definidas pelo número de filiados no dia da eleição da Mesa, considerando-se as mudanças de filiação.","Art. 8º, § 4º.","considera migrações")
R("R28",["8"],"troca_efeito",3,"O membro da Mesa que mudar de legenda partidária perde automaticamente o cargo que ocupa.","O membro da Mesa que mudar de legenda partidária perde o cargo apenas por decisão do Plenário.","Art. 8º, § 5º.","exige decisão")
# R29 Líderes, Blocos, Maioria e Minoria
R("R29",["9"],"troca_efeito",3,"Cada Líder pode indicar Vice-Líderes, na proporção de um por quatro Deputados, ou fração, que constituam sua representação.","Cada Líder pode indicar Vice-Líderes, na proporção de um por dez Deputados, vedada a fração.","Art. 9º, § 1º.","troca proporção")
R("R29",["9"],"troca_efeito",3,"A escolha do Líder é comunicada à Mesa em documento subscrito pela maioria absoluta dos integrantes da representação.","A escolha do Líder é comunicada à Mesa em documento subscrito por dois terços dos integrantes da representação.","Art. 9º, § 2º.","troca quórum")
R("R29",["9"],"troca_efeito",3,"O Partido sem Liderança pode indicar um integrante para fazer uso da palavra uma vez por semana, por cinco minutos, nas Comunicações de Lideranças.","O Partido sem Liderança pode indicar um integrante para fazer uso da palavra todos os dias, por dez minutos.","Art. 9º, § 4º.","troca frequência e tempo")
R("R29",["9"],"troca_efeito",2,"Os Líderes e Vice-Líderes não podem integrar a Mesa.","Os Líderes podem integrar a Mesa, mas não os Vice-Líderes.","Art. 9º, § 5º.","separa Líder e Vice")
R("R29",["10"],"troca_efeito",3,"O Líder pode participar dos trabalhos de qualquer Comissão de que não seja membro, sem direito a voto, podendo encaminhar a votação ou requerer verificação.","O Líder pode participar dos trabalhos de qualquer Comissão de que não seja membro, com direito a voto, mas sem poder requerer verificação.","Art. 10, III.","troca prerrogativas")
R("R29",["10"],"troca_efeito",3,"O Líder pode encaminhar a votação de qualquer proposição do Plenário, para orientar sua bancada, por tempo não superior a um minuto.","O Líder pode encaminhar a votação de qualquer proposição do Plenário por tempo não superior a cinco minutos.","Art. 10, IV.","troca o tempo")
R("R29",["10"],"atribuicao_autor",3,"Cabe ao Líder indicar à Mesa os membros da bancada para compor as Comissões e, a qualquer tempo, substituí-los.","Cabe ao Presidente da Câmara indicar os membros de cada bancada nas Comissões, vedada a substituição pelo Líder.","Art. 10, VI.","atribui ao Presidente")
R("R29",["11"],"troca_efeito",3,"A Liderança do Governo é composta por Líder e vinte Vice-Líderes, com as prerrogativas dos incisos I, III e IV do art. 10.","A Liderança do Governo é composta por Líder e dez Vice-Líderes, com todas as prerrogativas do art. 10.","Art. 11.","troca número e prerrogativas")
R("R29",["11A"],"troca_efeito",3,"A Liderança da Minoria é composta de Líder e nove Vice-Líderes, indicados pelo Líder da Minoria dentre os partidos que expressem posição contrária à da Maioria.","A Liderança da Minoria é composta de Líder e vinte Vice-Líderes, indicados pelo Presidente da Câmara.","Art. 11-A.","troca número e indicador")
R("R29",["12"],"troca_efeito",3,"Dois ou mais Partidos podem constituir Bloco Parlamentar sob Liderança comum, por deliberação das respectivas bancadas.","Dois ou mais Partidos podem constituir Bloco Parlamentar por decisão do Presidente da Câmara, mantidas as Lideranças.","Art. 12.","troca competência")
R("R29",["12"],"troca_efeito",3,"As Lideranças dos Partidos que se coligarem em Bloco perdem suas atribuições e prerrogativas regimentais.","As Lideranças dos Partidos que se coligarem em Bloco mantêm suas prerrogativas regimentais plenas.","Art. 12, § 2º.","mantém as prerrogativas")
R("R29",["12"],"troca_efeito",4,"Não se admite Bloco Parlamentar composto de menos de três centésimos dos membros da Câmara; se o desligamento de bancada implicar essa perda, o Bloco se extingue.","Não se admite Bloco Parlamentar composto de menos de dez centésimos dos membros da Câmara; se o desligamento implicar essa perda, o Bloco subsiste por mais uma sessão legislativa.","Art. 12, §§ 3º e 4º.","troca percentual e efeito")
R("R29",["12"],"troca_efeito",3,"O Bloco Parlamentar tem existência circunscrita à legislatura, devendo o ato de criação e as alterações ser apresentados à Mesa para registro e publicação.","O Bloco Parlamentar tem existência por prazo indeterminado, atravessando legislaturas, e dispensa registro na Mesa.","Art. 12, § 5º.","amplia a duração")
R("R29",["12"],"troca_efeito",4,"A agremiação que integrava Bloco dissolvido, ou que dele se desvinculou, não pode constituir ou integrar outro na mesma sessão legislativa; nem integrar dois ao mesmo tempo.","A agremiação que se desvinculou de Bloco pode integrar outro imediatamente, mas não dois ao mesmo tempo.","Arts. 12, §§ 8º e 9º.","omite a quarentena")
R("R29",["13"],"conceito_correto",3,"Constitui a Maioria o Partido ou Bloco integrado pela maioria absoluta dos membros da Casa; Minoria é a representação imediatamente inferior que, em relação ao Governo, expresse posição diversa.","Constitui a Maioria o Partido ou Bloco com o maior número de representantes; Minoria é o segundo maior, independentemente de sua posição em relação ao Governo.","Art. 13.","troca o critério")
R("R29",["13"],"excecao_omitida",3,"Se nenhuma representação atingir a maioria absoluta, assume as funções da Maioria o Partido ou Bloco que tiver o maior número de representantes.","Se nenhuma representação atingir a maioria absoluta, não há Maioria, e suas funções são exercidas pela Mesa.","Art. 13, p. único.","troca por Mesa")
R("R29",["13A"],"troca_efeito",3,"A Bancada Negra é constituída de uma Coordenação-Geral e três Vices-Coordenadorias, e a autodeclaração racial considerada é a lançada no registro de candidatura da eleição geral anterior à legislatura.","A Bancada Negra é constituída de um Líder e dois Vice-Líderes, e a autodeclaração considerada é a prestada na posse.","Art. 13-A.","troca estrutura e fonte")
R("R29",["20"],"troca_efeito",3,"Os Líderes da Maioria, da Minoria, dos Partidos, dos Blocos e do Governo constituem o Colégio de Líderes.","Os Líderes da Maioria, da Minoria, dos Partidos e dos Blocos constituem o Colégio de Líderes; o Líder do Governo não o integra.","Art. 20, caput.","exclui o Governo")
R("R29",["20"],"troca_efeito",4,"Os Líderes de Partidos integrantes de Bloco e o Líder do Governo têm voz, mas não voto, no Colégio de Líderes.","Os Líderes de Partidos integrantes de Bloco e o Líder do Governo têm voz e voto no Colégio de Líderes.","Art. 20, § 1º.","concede voto")
R("R29",["20"],"troca_efeito",3,"As deliberações do Colégio de Líderes buscam o consenso; não sendo possível, prevalece a maioria absoluta, ponderados os votos em função da expressão numérica de cada bancada.","As deliberações do Colégio de Líderes são tomadas por maioria simples, cada Líder com um voto de igual peso.","Art. 20, § 2º.","iguala os votos")
# R30 Mesa
R("R30",["14"],"conceito_correto",2,"A Mesa, na qualidade de Comissão Diretora, dirige os trabalhos legislativos e os serviços administrativos da Câmara.","A Mesa, na qualidade de Comissão Representativa, dirige os trabalhos legislativos mas não os serviços administrativos.","Art. 14.","troca denominação e escopo")
R("R30",["14"],"troca_efeito",3,"A Mesa compõe-se de Presidência (Presidente e dois Vice-Presidentes) e Secretaria (quatro Secretários), com quatro Suplentes de Secretário.","A Mesa compõe-se de Presidente, quatro Vice-Presidentes e dois Secretários, com dois Suplentes de Secretário.","Art. 14, §§ 1º e 2º.","troca composição")
R("R30",["14"],"troca_efeito",3,"A Mesa reúne-se ordinariamente uma vez por quinzena e, extraordinariamente, quando convocada pelo Presidente ou por quatro de seus membros efetivos.","A Mesa reúne-se ordinariamente uma vez por semana e, extraordinariamente, quando convocada pelo Presidente ou por dois de seus membros.","Art. 14, § 3º.","troca periodicidade e quórum")
R("R30",["14"],"troca_efeito",3,"Perde o lugar o membro da Mesa que deixar de comparecer a cinco reuniões ordinárias consecutivas sem causa justificada.","Perde o lugar o membro da Mesa que deixar de comparecer a três reuniões ordinárias alternadas, ainda que justificadas.","Art. 14, § 4º.","troca número e justificativa")
R("R30",["14"],"troca_efeito",3,"Os membros efetivos da Mesa não podem fazer parte de Liderança nem de Comissão Permanente, Especial ou de Inquérito.","Os membros efetivos da Mesa não podem fazer parte de Liderança, mas podem integrar Comissões Permanentes.","Art. 14, § 5º.","permite Comissão")
R("R30",["14"],"troca_efeito",3,"A Mesa fixa, em ato publicado em trinta sessões após sua constituição, a competência de cada um de seus membros.","A Mesa fixa, em ato publicado em cinco sessões após sua constituição, a competência de cada membro, vedada a prevalência da anterior.","Art. 14, § 6º.","troca prazo e prevalência")
R("R30",["15"],"troca_efeito",4,"Compete à Mesa propor ação de inconstitucionalidade, por iniciativa própria ou a requerimento de Deputado ou Comissão.","Compete à Mesa propor ação de inconstitucionalidade somente a requerimento da CCJC.","Art. 15, IV.","restringe a provocação")
R("R30",["15"],"troca_efeito",3,"Compete à Mesa promulgar, juntamente com a Mesa do Senado Federal, emendas à Constituição.","Compete ao Presidente da Câmara promulgar, sozinho, emendas à Constituição.","Art. 15, III.","atribui ao Presidente")
R("R30",["15"],"troca_efeito",4,"A Mesa constitui, excluído o seu Presidente, alternadamente com a Mesa do Senado, a Mesa do Congresso Nacional.","A Mesa constitui, incluído o seu Presidente, simultaneamente com a Mesa do Senado, a Mesa do Congresso Nacional.","Art. 15, II.","inclui o Presidente")
R("R30",["15"],"atribuicao_autor",3,"Compete à Mesa aplicar a penalidade de censura escrita a Deputado.","Compete ao Presidente, isoladamente, aplicar a penalidade de censura escrita a Deputado.","Art. 15, XV.","atribui ao Presidente")
R("R30",["15"],"atribuicao_autor",4,"A censura verbal é aplicada pelo Presidente, e a censura escrita, pela Mesa.","A censura verbal e a escrita são aplicadas pelo Presidente.","Arts. 15, XV; 17, I, x.","funde as competências")
R("R30",["15"],"troca_efeito",4,"Compete privativamente à Mesa propor à Câmara projeto de resolução sobre sua organização, funcionamento, polícia, regime jurídico do pessoal e criação ou extinção de cargos.","Compete à CCJC propor projeto de resolução sobre a organização e o regime jurídico do pessoal da Câmara.","Art. 15, XVII.","atribui à CCJC")
R("R30",["15"],"troca_efeito",4,"A Mesa declara a perda do mandato de Deputado nos casos dos incisos III, IV e V do art. 55 da Constituição, observado o § 3º do mesmo artigo.","A Mesa declara a perda do mandato de Deputado nos casos dos incisos I, II e VI do art. 55 da Constituição.","Art. 15, XIV.","troca incisos")
R("R30",["15"],"troca_efeito",4,"A Mesa propõe a suspensão cautelar do mandato no prazo decadencial de cinco dias úteis, e o Conselho de Ética a decide em três dias úteis, em votação ostensiva.","A Mesa propõe a suspensão cautelar do mandato no prazo de trinta dias, e o Conselho de Ética a decide em votação secreta.","Art. 15, §§ 2º e 3º.","troca prazo e votação")
R("R30",["15"],"troca_efeito",4,"Da decisão do Conselho de Ética sobre a suspensão cautelar cabe recurso ao Plenário, que exige maioria absoluta para aprovar ou manter a suspensão.","Da decisão do Conselho de Ética sobre a suspensão cautelar não cabe recurso, por ser decisão terminativa.","Art. 15, § 4º.","nega o recurso")
R("R30",["15"],"troca_efeito",4,"Em matéria inadiável, o Presidente pode decidir ad referendum da Mesa, exceto quanto à suspensão cautelar do mandato.","Em matéria inadiável, o Presidente pode decidir ad referendum da Mesa em qualquer assunto, inclusive na suspensão cautelar.","Art. 15, § 1º.","omite a exceção")
# R31 Presidente, Vices e Secretários
R("R31",["16"],"troca_efeito",3,"O cargo de Presidente da Câmara é privativo de brasileiro nato.","O cargo de Presidente da Câmara é privativo de brasileiro nato ou naturalizado há mais de dez anos.","Art. 16, p. único.","amplia")
R("R31",["17"],"atribuicao_autor",3,"Cabe ao Presidente nomear Comissão Especial, ouvido o Colégio de Líderes.","Cabe ao Plenário nomear Comissão Especial, ouvida a Mesa.","Art. 17, I, m.","troca o nomeante")
R("R31",["17"],"atribuicao_autor",3,"Cabe ao Presidente organizar, ouvido o Colégio de Líderes, a agenda mensal com a previsão das proposições a serem apreciadas.","Cabe à Mesa organizar, por maioria, a agenda anual das proposições a serem apreciadas.","Art. 17, I, s.","troca órgão e periodicidade")
R("R31",["17"],"troca_efeito",3,"O Presidente desempata as votações ostensivas e vota em escrutínio secreto, contando-se sua presença, em qualquer caso, para efeito de quórum.","O Presidente vota em todas as votações nominais e não vota em escrutínio secreto.","Art. 17, I, v.","inverte o voto")
R("R31",["17"],"troca_efeito",3,"O Presidente não pode, senão na qualidade de membro da Mesa, oferecer proposição nem votar em Plenário, exceto em escrutínio secreto ou para desempatar votação ostensiva.","O Presidente pode oferecer proposição como Deputado e votar em qualquer votação ostensiva.","Art. 17, § 1º.","amplia as hipóteses")
R("R31",["17"],"troca_efeito",3,"Para tomar parte em discussão, o Presidente transmite a presidência ao substituto e não a reassume enquanto se debater a matéria.","Para tomar parte em discussão, o Presidente continua presidindo a sessão, mas sem direito a voto.","Art. 17, § 2º.","mantém a presidência")
R("R31",["17"],"atribuicao_autor",3,"Cabe ao Presidente, nos termos do art. 80 da Constituição, substituir o Presidente da República, e integrar o Conselho da República e o Conselho de Defesa Nacional.","Cabe ao Presidente integrar o Conselho da República, mas não o Conselho de Defesa Nacional.","Art. 17, VI, a e b.","exclui um Conselho")
R("R31",["17"],"atribuicao_autor",3,"Cabe ao Presidente promulgar as resoluções da Câmara e assinar os atos da Mesa.","Cabe ao Primeiro-Secretário promulgar as resoluções da Câmara.","Art. 17, VI, m.","atribui ao Secretário")
R("R31",["17"],"atribuicao_autor",3,"Cabe ao Presidente declarar a vacância do mandato nos casos de falecimento ou renúncia de Deputado.","Cabe à Mesa declarar a vacância do mandato nos casos de falecimento ou renúncia de Deputado.","Art. 17, VI, f.","atribui à Mesa")
R("R31",["17"],"atribuicao_autor",3,"O Presidente dirige, com suprema autoridade, a polícia da Câmara.","O Primeiro-Secretário dirige, com suprema autoridade, a polícia da Câmara.","Art. 17, VI, h.","atribui ao Secretário")
R("R31",["17"],"troca_efeito",3,"O Presidente pode delegar aos Vice-Presidentes competência que lhe seja própria.","O Presidente não pode delegar competência própria, que é indelegável.","Art. 17, § 4º.","nega a delegação")
R("R31",["18"],"troca_efeito",3,"Quando tiver de ausentar-se da Capital Federal por mais de quarenta e oito horas, o Presidente passa o exercício ao Primeiro-Vice-Presidente ou, na ausência deste, ao Segundo.","Quando tiver de ausentar-se da Capital Federal por mais de oito dias, o Presidente passa o exercício ao Primeiro-Secretário.","Art. 18, § 1º.","troca prazo e substituto")
R("R31",["18"],"troca_efeito",4,"À hora do início da sessão, sem o Presidente no recinto, ele é substituído pelos Vice-Presidentes, Secretários e Suplentes, ou, finalmente, pelo Deputado mais idoso dentre os de maior número de legislaturas.","À hora do início da sessão, sem o Presidente no recinto, ele é substituído pelo Líder da Maioria.","Art. 18, § 2º.","troca o substituto")
R("R31",["19"],"atribuicao_autor",3,"Cabe ao Primeiro-Secretário superintender os serviços administrativos da Câmara e dar posse ao Diretor-Geral e ao Secretário-Geral da Mesa.","Cabe ao Presidente superintender os serviços administrativos da Câmara, restando ao Primeiro-Secretário apenas a correspondência.","Art. 19.","atribui ao Presidente")
R("R31",["19"],"troca_efeito",3,"Os Secretários, ao integrarem a Mesa durante a sessão, só podem usar a palavra para chamada, contagem de votos ou leitura de documentos ordenada pelo Presidente.","Os Secretários, ao integrarem a Mesa, podem usar livremente a palavra para encaminhar votações.","Art. 19, § 3º.","amplia a palavra")
R("R31",["19A"],"troca_efeito",3,"Os Suplentes de Secretário substituem os Secretários em suas faltas e podem funcionar como Relatores em assuntos não reservados a outros membros da Mesa.","Os Suplentes de Secretário não participam das reuniões da Mesa, salvo convocação do Presidente.","Art. 19-A, I e III.","exclui da Mesa")
# R32 órgãos: Ouvidoria, Procuradoria, Corregedoria, Conselho de Ética, Secretarias
R("R32",["20A"],"troca_efeito",3,"A Secretaria da Mulher é composta pela Procuradoria da Mulher e pela Coordenadoria dos Direitos da Mulher, sem relação de subordinação entre elas.","A Secretaria da Mulher é composta pela Procuradoria da Mulher e pela Coordenadoria, esta subordinada àquela.","Art. 20-A.","cria subordinação")
R("R32",["20B"],"troca_efeito",3,"A Procuradoria da Mulher tem uma Procuradora e três Adjuntas, eleitas pelas deputadas, com mandato de dois anos, vedada a recondução.","A Procuradoria da Mulher tem uma Procuradora e cinco Adjuntas, eleitas pelo Presidente, com mandato de quatro anos, permitida a recondução.","Art. 20-B.","troca estrutura, eleitores e mandato")
R("R32",["21"],"troca_efeito",3,"A Procuradoria Parlamentar defende a Câmara, seus órgãos e membros quando atingidos em sua honra ou imagem em razão do exercício do mandato; é constituída de onze membros designados pelo Presidente.","A Procuradoria Parlamentar defende apenas os Deputados em processos criminais; é constituída de sete membros eleitos pelo Plenário.","Art. 21.","troca finalidade e composição")
R("R32",["21A"],"atribuicao_autor",3,"Compete à Ouvidoria Parlamentar receber e encaminhar reclamações sobre violações de direitos, ilegalidades, abuso de poder e mau funcionamento dos serviços da Casa.","Compete à Ouvidoria Parlamentar julgar as reclamações sobre violações de direitos e aplicar as sanções cabíveis aos servidores.","Art. 21-A.","atribui poder punitivo")
R("R32",["21B"],"troca_efeito",3,"A Ouvidoria Parlamentar é composta de um Ouvidor-Geral e dois Substitutos, designados pelo Presidente dentre os membros da Casa a cada dois anos, vedada a recondução no período subsequente.","A Ouvidoria Parlamentar é composta de um Ouvidor-Geral e quatro Substitutos, eleitos pelo Plenário a cada quatro anos.","Art. 21-B.","troca composição e forma")
R("R32",["21E"],"troca_efeito",3,"O Conselho de Ética e Decoro Parlamentar tem vinte e um membros titulares e igual número de suplentes, mandato de dois anos, e elege entre os titulares um Presidente e dois Vice-Presidentes.","O Conselho de Ética e Decoro Parlamentar tem quinze membros titulares e sete suplentes, mandato de um ano, e é presidido pelo Presidente da Câmara.","Art. 21-E.","troca composição e presidência")
R("R32",["21F"],"atribuicao_autor",3,"Compete à Corregedoria Parlamentar manter o decoro, a ordem e a disciplina, cumprir as determinações da Mesa sobre segurança e promover sindicância ou inquérito sobre ilícitos que envolvam Deputados.","Compete à Corregedoria Parlamentar examinar as condutas puníveis e propor penalidades aos Deputados no processo disciplinar por quebra de decoro.","Art. 21-F.","confunde com o Conselho de Ética")
R("R32",["21F"],"restricao_indevida",4,"Nas hipóteses de perda de mandato dos incisos IV e V do art. 55 da Constituição, a análise na Câmara se restringe aos aspectos formais da decisão judicial.","Nas hipóteses de perda de mandato dos incisos IV e V do art. 55 da Constituição, a Câmara reexamina o mérito da decisão judicial.","Art. 21-F, p. único.","admite reexame do mérito")
R("R32",["21G"],"troca_efeito",3,"A Corregedoria Parlamentar é composta por um Corregedor e três Substitutos, designados pelo Presidente para mandato de dois anos, vedada a recondução no período subsequente.","A Corregedoria Parlamentar é composta por um Corregedor e dois Substitutos, eleitos pelo Plenário para mandato de dois anos, permitida a recondução.","Art. 21-G.","troca composição e forma")
R("R32",["21I"],"troca_efeito",3,"O Secretário de Relações Internacionais é escolhido pelo Presidente dentre os Deputados em exercício, podendo ser substituído a qualquer tempo.","O Secretário de Relações Internacionais é escolhido pela Mesa, com mandato fixo de dois anos.","Art. 21-I.","troca escolha e mandato")
